def parse_tags(text):
    """Split a comma-separated tag list: 'Python, Rust' -> ['python', 'rust']."""
    return [t.strip().lower() for t in text.split(",") if t.strip()]

def parse_tags(text):
    """Split a comma-separated tag list: 'Python, Rust' -> ['python', 'rust']."""
    if not text:
        raise ValueError("no tags")
    return [t.strip().lower() for t in text.split(",") if t.strip()]
